// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Ensure caller is the current owner
        vm.startPrank(address(this));
        c.transferOwnership(newOwner);
        vm.stopPrank();

        // After transferOwnership, owner() must equal the new owner
        address currentOwner = c.owner();
        assertTrue(currentOwner == newOwner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _distributor) public {
        address oldDistributor = c.rewardDistributor();
        c.setRewardDistributor(_distributor);
        address newDistributor = c.rewardDistributor();
        assert(newDistributor == _distributor);
    }
}

